def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Integer Newton's method; exact, no floating point involved.
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    # x is now the largest integer with x*x <= n (integer floor sqrt).
    if x * x != n:
        raise ValueError("%d is not a perfect square" % n)
    return x

